package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.verifyCheckSum.
 * Note: CHKSUM_OFFSET is 148 and CHKSUMLEN is 8 in standard Tar implementation.
 */
public class TarUtils_verifyCheckSum_TriageGen1Test {

    private static final int CHKSUM_OFFSET = 148;
    private static final int CHKSUMLEN = 8;

    @Test
    public void testVerifyCheckSum_MatchUnsigned() {
        byte[] header = new byte[512];
        // Fill header with 0s
        for (int i = 0; i < 512; i++) header[i] = 0;

        // Calculate expected sum: 
        // The loop skips CHKSUM_OFFSET to CHKSUM_OFFSET + CHKSUMLEN for sum calculation by setting b = ' '
        // ' ' is 32. Total sum = 512 * 0 (if all 0) but we must account for the ' ' replacement.
        // Actually, the loop: unsignedSum += 0xff & b;
        // If we set everything to 0, then the checksum part becomes ' ', which is 32.
        // There are 8 bytes in the checksum range. 8 * 32 = 256.
        // However, the checksum part in the array is replaced by ' ' in the sum calculation.

        // Let's build a valid header manually.
        // 1. Set content so sum is X.
        // 2. Set checksum field to octal of X.

        // Let's use a simpler approach: 
        // If we want unsignedSum == storedSum.
        // Let's make all bytes 0, except the checksum field.
        // But the checksum field bytes are replaced by ' ' (32) in the sum.
        // So unsignedSum = (512 - 8) * 0 + 8 * 32 = 256.
        // We need storedSum to be 256.
        // 256 in octal is 400.

        byte[] header2 = new byte[512];
        // Set checksum field (offset 148) to "0000400"
        header2[148] = '0';
        header2[149] = '0';
        header2[150] = '0';
        header2[151] = '0';
        header2[152] = '4';
        header2[153] = '0';
        header2[154] = '0';
        header2[155] = '0'; // 7th digit

        // Sum calculation:
        // bytes 0-147: 0
        // bytes 148-155: replaced by ' ' (32) -> 8 * 32 = 256
        // bytes 156-511: 0
        // Total unsignedSum = 256.
        // storedSum = 400 (octal) = 256.
        assertTrue(TarUtils.verifyCheckSum(header2));
    }

    @Test
    public void testVerifyCheckSum_MatchSigned() {
        byte[] header = new byte[512];
        // For signed sum to match, we use bytes that are the same for signed and unsigned (0-127)
        // Let's use the same logic as above.
        header[148] = '0';
        header[149] = '0';
        header[150] = '0';
        header[151] = '0';
        header[152] = '4';
        header[153] = '0';
        header[154] = '0';
        header[155] = '0';

        // unsignedSum = 256, signedSum = 256.
        assertTrue(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_GreaterCondition() {
        byte[] header = new byte[512];
        // storedSum = 1000 (octal) = 512.
        // unsignedSum = 256 (from the ' ' replacement).
        // 512 > 256, should return true (COMPRESS-177).
        header[148] = '1';
        header[149] = '0';
        header[150] = '0';
        header[151] = '0';
        header[152] = '0';
        header[153] = '0';
        header[154] = '0';
        header[155] = '0';

        assertTrue(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_Fail() {
        byte[] header = new byte[512];
        // We want storedSum < unsignedSum and storedSum != unsignedSum and storedSum != signedSum.
        // unsignedSum is 256 (8 * 32).
        // Let's set storedSum to 1 (octal).
        header[148] = '0';
        header[149] = '0';
        header[150] = '0';
        header[151] = '0';
        header[152] = '0';
        header[153] = '0';
        header[154] = '0';
        header[155] = '1';

        // storedSum = 1.
        // unsignedSum = 256.
        // 1 < 256 and 1 != 256.
        assertFalse(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_DigitsLimit() {
        byte[] header = new byte[512];
        // Test the "digits++ < 6" and "digits = 6" logic.
        // If we provide more than 6 octal digits, it should stop parsing the value 
        // but still consume the bytes for the sum.

        // "1234567" -> digits will reach 6 with '123456'. 
        // Then '7' is encountered. Since digits (6) is not < 6, it goes to else if (digits > 0).
        // digits becomes 6.
        // storedSum = 123456 (octal) = 42814.

        header[148] = '1';
        header[149] = '2';
        header[150] = '3';
        header[151] = '4';
        header[152] = '5';
        header[153] = '6';
        header[154] = '7';
        header[155] = '0';

        // unsignedSum = 8 * 32 = 256.
        // storedSum = 42814.
        // 42814 > 256 -> true.
        assertTrue(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_NonOctalInChecksumRange() {
        byte[] header = new byte[512];
        // If the first digit in the checksum range is not '0'-'7'.
        // e.g., '8'.
        header[148] = '8'; 
        header[149] = '0';
        header[150] = '0';
        header[151] = '0';
        header[152] = '0';
        header[153] = '0';
        header[154] = '0';
        header[155] = '0';

        // storedSum = 0.
        // unsignedSum = 256.
        // 0 < 256 -> false.
        assertFalse(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_SignedNegative() {
        byte[] header = new byte[512];
        // To test signedSum, we need a byte that is negative when cast to byte.
        // e.g., 0xFF (which is -1).
        // If header[0] = -1.
        // unsignedSum = (0xff & -1) + ... = 255 + ...
        // signedSum = -1 + ...

        header[0] = (byte) 0xFF; 
        // Set checksum range to ' ' (32) to make sum calculation predictable.
        // Actually the code replaces the checksum range bytes with ' '.
        // So unsignedSum = 255 (from header[0]) + 8 * 32 (from checksum range) = 255 + 256 = 511.
        // signedSum = -1 (from header[0]) + 8 * 32 (from checksum range) = -1 + 256 = 255.

        // Let's set storedSum to 255.
        // 255 in octal is 377.
        header[148] = '0';
        header[149] = '0';
        header[150] = '0';
        header[151] = '0';
        header[152] = '3';
        header[153] = '7';
        header[154] = '7';
        header[155] = '0';

        // storedSum = 255.
        // signedSum = 255.
        // 255 == 255 -> true.
        assertTrue(TarUtils.verifyCheckSum(header));
    }
}
